#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Funds the EAS schema deployer wallet on every supported chain where it is
# empty: the chains added on 2026-10-15 (Scroll, Ink, Base Sepolia, Ink
# Sepolia), Celo and Celo Sepolia (added 2026-10-19), plus Arbitrum One,
# which was never funded. Pure action stages:
# nothing is captured or written. Every stage is skipped automatically once
# the chain reads as funded, so re-running is safe.

cd "$(dirname "$0")"   # scripts/, where .env and the Dart tools live

TOTAL_STAGES=9

# balance_ok CHAIN_ID: success when the deployer holds enough gas there.
balance_ok() {
  dart run check_deployer_balances.dart --chains "$1" >/dev/null 2>&1
}

# show_balances [CHAIN_ID]: prints the balance table (all chains by default).
show_balances() {
  if [[ $# -gt 0 ]]; then
    dart run check_deployer_balances.dart --chains "$1" || true
  else
    dart run check_deployer_balances.dart || true
  fi
}

# wait_until_funded CHAIN_ID NAME: re-checks the balance until it is enough
# or the human chooses to move on (the chain is then listed as still to do).
wait_until_funded() {
  local id="$1" name="$2"
  while true; do
    pause "Press Enter once the transfer has confirmed to re-check $name"
    if balance_ok "$id"; then
      printf '  %s✓ %s is funded%s\n' "$GREEN" "$name" "$RESET"
      pause
      return 0
    fi
    show_balances "$id"
    if ! confirm "Still not funded. Keep waiting on $name?"; then
      SKIPPED+=("fund the deployer on $name (chain $id), then re-run this wizard")
      return 0
    fi
  done
}

banner "Fund the EAS schema deployer on the new chains"

# ── Stage 1: where we stand ───────────────────────────────────────────────
stage "Deployer address and current balances"
say "The deployer address is derived from DEPLOYER_PRIVATE_KEY in scripts/.env."
say "Copy it from the first line below: every transfer in this wizard goes to it."
printf '\n'
show_balances
printf '\n'
note "A chain is 'funded' at 0.0005 ETH or more; one SchemaRegistry.register on an L2 costs far less."
note "Celo chains pay gas in CELO and count as funded at 0.1 CELO."
pause

# ── Stage 2: Arbitrum One ─────────────────────────────────────────────────
stage "Arbitrum One (chain 42161): bridge ETH"
if balance_ok 42161; then
  say "Already funded, skipping."; pause
else
  say "Arbitrum One has been in the catalog since the start but the deployer never held ETH there,"
  say "so the schema is still unregistered on it. Target about 0.002 ETH."
  say "Cheapest path: send from Base or Optimism through a cross-L2 bridge such as Relay or Jumper."
  say "Official path: the Arbitrum bridge from Ethereum mainnet."
  printf '\n'
  open_url "https://bridge.arbitrum.io"
  step "Connect the funding wallet, choose Ethereum → Arbitrum One, enter about 0.002 ETH."
  step "Set the recipient to the deployer address (expand 'Custom destination address' if the bridge offers it)."
  note "If the bridge only delivers to the connected wallet, bridge to that wallet, then send to the deployer on Arbitrum One."
  step "Approve the transaction and wait for it to arrive."
  wait_until_funded 42161 "Arbitrum One"
fi

# ── Stage 3: Scroll mainnet ───────────────────────────────────────────────
stage "Scroll (chain 534352): bridge ETH"
if balance_ok 534352; then
  say "Already funded, skipping."; pause
else
  say "Scroll uses ETH for gas. Bridge about 0.002 ETH to the deployer address."
  say "Cheapest path: send from Base or Optimism, where the deployer already has ETH,"
  say "through a cross-L2 bridge such as Relay or Jumper (any wallet, ~1 minute)."
  say "Official path: the Scroll Portal bridge from Ethereum mainnet (slower, L1 gas)."
  printf '\n'
  open_url "https://portal.scroll.io/bridge"
  step "Connect the wallet that holds the ETH you are sending."
  step "Pick the source network, enter about 0.002 ETH, set the recipient to the deployer address."
  note "If the bridge only delivers to the connected wallet, bridge to that wallet, then send to the deployer on Scroll."
  step "Approve the transaction and wait for it to finalize on Scroll."
  wait_until_funded 534352 "Scroll"
fi

# ── Stage 4: Ink mainnet ──────────────────────────────────────────────────
stage "Ink (chain 57073): bridge or withdraw ETH"
if balance_ok 57073; then
  say "Already funded, skipping."; pause
else
  say "Ink is an OP Stack L2 that uses ETH for gas. Target about 0.002 ETH."
  say "Two ways in:"
  step "Kraken: withdraw ETH and choose the Ink network, recipient = deployer address."
  step "Bridge: the Ink bridge accepts ETH from Ethereum, Base and Optimism."
  printf '\n'
  open_url "https://inkonchain.com/bridge"
  step "Connect the funding wallet, choose the source chain, enter the amount, and set the recipient to the deployer address."
  note "If the bridge only delivers to the connected wallet, bridge to that wallet, then send to the deployer on Ink."
  step "Approve the transaction and wait for it to arrive on Ink."
  wait_until_funded 57073 "Ink"
fi

# ── Stage 5: Celo mainnet ─────────────────────────────────────────────────
stage "Celo (chain 42220): buy or swap for CELO"
if balance_ok 42220; then
  say "Already funded, skipping."; pause
else
  say "Celo pays gas in CELO, not ETH. Gas runs near 200 gwei, so one register costs about 0.05 CELO."
  say "Target about 1 CELO; the check counts 0.1 CELO or more as funded."
  say "Two ways in:"
  step "Exchange: buy CELO on Coinbase, Kraken or Binance and withdraw on the Celo network, recipient = deployer address."
  step "Swap: Jumper or Squid can turn ETH or USDC on Base or Optimism into native CELO on Celo."
  warn "Do not use a plain ETH bridge: it lands ETH as a token on Celo, which cannot pay gas here."
  printf '\n'
  open_url "https://jumper.exchange"
  step "Connect the funding wallet, set the destination to Celo with CELO as the token, and set the recipient to the deployer address."
  note "If the swap only delivers to the connected wallet, swap to that wallet, then send the CELO to the deployer on Celo."
  step "Approve the transaction and wait for it to arrive on Celo."
  wait_until_funded 42220 "Celo"
fi

# ── Stage 6: Base Sepolia ─────────────────────────────────────────────────
stage "Base Sepolia (chain 84532): faucet or bridge"
if balance_ok 84532; then
  say "Already funded, skipping."; pause
else
  say "Testnet ETH is free. Pick whichever faucet you already have an account for:"
  step "Superchain faucet (Optimism console; needs a GitHub or onchain-identity sign-in). Select Base Sepolia, paste the deployer address."
  step "Coinbase Developer Platform faucet (Coinbase account). Select Base Sepolia, paste the deployer address."
  step "Or bridge Sepolia ETH you already hold through Superbridge to Base Sepolia."
  printf '\n'
  open_url "https://console.optimism.io/faucet"
  note "Fallbacks: https://portal.cdp.coinbase.com/products/faucet  or  https://superbridge.app/base-sepolia"
  step "Request the drip (0.05 to 0.1 ETH is typical) and wait for it to land."
  wait_until_funded 84532 "Base Sepolia"
fi

# ── Stage 7: Ink Sepolia ──────────────────────────────────────────────────
stage "Ink Sepolia (chain 763373): faucet"
if balance_ok 763373; then
  say "Already funded, skipping."; pause
else
  say "Testnet ETH is free. The official Ink faucet drips straight to any address."
  printf '\n'
  open_url "https://inkonchain.com/faucet"
  step "Paste the deployer address and request the drip."
  note "The Superchain faucet (https://console.optimism.io/faucet) also lists Ink Sepolia if the Ink faucet is rate-limited."
  wait_until_funded 763373 "Ink Sepolia"
fi

# ── Stage 8: Celo Sepolia ─────────────────────────────────────────────────
stage "Celo Sepolia (chain 11142220): faucet"
if balance_ok 11142220; then
  say "Already funded, skipping."; pause
else
  say "Testnet CELO is free. The official Celo faucet drips straight to any address."
  printf '\n'
  open_url "https://faucet.celo.org/celo-sepolia"
  step "Paste the deployer address and request the drip."
  note "Signing in with GitHub raises the drip size if the anonymous amount falls short of 0.1 CELO."
  wait_until_funded 11142220 "Celo Sepolia"
fi

# ── Stage 9: final check and hand-off ─────────────────────────────────────
stage "Final balance check"
printf '\n'
if show_balances && dart run check_deployer_balances.dart >/dev/null 2>&1; then
  printf '\n'
  say "Every chain is funded. Register the schema everywhere it is missing with:"
  note "  dart run register_lp_eas_schema.dart --dry-run   # confirm the list first"
  note "  dart run register_lp_eas_schema.dart             # registers only where absent"
else
  printf '\n'
  warn "Some chains still need gas. Fund them, then re-run this wizard; funded stages skip themselves."
fi
pause

finish
